void Update(){double now=Time.realtimeSinceStartupAsDouble,dt=Math.Max(0,now-lastTick);lastTick=now;if(Input.GetKeyDown(KeyCode.Escape)){if(s!=null&&page!="标题"){paused=!paused;settingsOpen=false;}else page="标题";}if(Input.GetKeyDown(KeyCode.F12)){string dir=Path.Combine(Application.persistentDataPath,"Screenshots");Directory.CreateDirectory(dir);ScreenCapture.CaptureScreenshot(Path.Combine(dir,DateTime.Now.ToString("yyyyMMdd-HHmmss")+".png"));Notify("截图已保存："+dir);}if(page=="标题"&&Input.anyKeyDown)titleReady=true;if(messageTime>0)messageTime-=(float)dt;eventElapsed+=(float)dt;shotEffect=Mathf.Max(0,shotEffect-(float)dt);if(s!=null){autoSave+=(float)dt;if(autoSave>30){Save(true);autoSave=0;}if(!paused){if(page=="城市"){characterPos=Vector2.MoveTowards(characterPos,walkTarget,(float)dt*240*s.settings.moveSpeed);if(walkAction!=""&&Vector2.Distance(characterPos,walkTarget)<5){page=walkAction;walkAction="";scroll=Vector2.zero;}}if(page=="航海"){s.heading+=(Input.GetKey(KeyCode.D)?1:Input.GetKey(KeyCode.A)?-1:0)*dt*1.7;if(Input.GetKey(KeyCode.W))throttle=Mathf.Min(1,throttle+(float)dt);if(Input.GetKey(KeyCode.S))throttle=Mathf.Max(.15f,throttle-(float)dt);s.trim=GameService.Clamp(s.trim+(Input.GetKey(KeyCode.E)?.5:Input.GetKey(KeyCode.Q)?-.5:0)*dt,0,1);g.Sail(Math.Min(.2,dt),throttle);}if(page=="战斗"){if(smoke){var dir=battleTarget-battlePlayer;battleAngle=Mathf.Atan2(dir.y,dir.x)+Mathf.PI/2;if(battleCooldown<=0)Fire();}BattleTick((float)Math.Min(.2,dt));}}}sound.Apply(s==null?menuSettings:s.settings,page);if(smoke&&Time.realtimeSinceStartup>nextScreenshot){smokeCaptureDue=true;nextScreenshot+=2;}}
