void Avatar(Rect r,Appearance a,float motion){float u=Mathf.Min(r.width/24,r.height/42);float x=r.x,y=r.y+motion;Color skin=Color.Lerp(new Color(.96f,.77f,.58f),new Color(.28f,.16f,.12f),a.skinId/5f),hair=palette[a.hairColor%palette.Length],coat=palette[a.primaryColor%8],trim=palette[a.secondaryColor%8];Fill(new Rect(x+(5+a.baseId%3)*u,y+4*u,(14-a.baseId%3*2)*u,(11+a.baseId%2)*u),skin);Fill(new Rect(x+5*u,y+2*u,14*u,(3+a.hairId%4)*u),hair);if(a.hairId==1||a.hairId==5)Fill(new Rect(x+4*u,y,u*5,u*4),hair);if(a.hairId==2||a.hairId==6)Fill(new Rect(x+15*u,y-u,u*4,u*4),hair);if(a.hairId>=4)Fill(new Rect(x+18*u,y+5*u,3*u,15*u),hair);Fill(new Rect(x+8*u,y+10*u,u,u),Color.black);Fill(new Rect(x+15*u,y+10*u,u,u),Color.black);Fill(new Rect(x+10*u,y+14*u,4*u,u),new Color(.5f,.23f,.2f));if(a.accessoryIds[2]>0)Fill(new Rect(x+2*u,y+17*u,21*u,18*u),trim);Fill(new Rect(x+5*u,y+17*u,15*u,15*u),coat);Fill(new Rect(x+11*u,y+17*u,2*u,15*u),trim);Fill(new Rect(x+2*u,y+18*u,3*u,11*u),coat);Fill(new Rect(x+20*u,y+18*u,3*u,11*u),coat);Fill(new Rect(x+6*u,y+32*u,5*u,9*u),palette[6]);Fill(new Rect(x+14*u,y+32*u,5*u,9*u),palette[6]);if(a.outfitId%2==1)Fill(new Rect(x+5*u,y+30*u,15*u,6*u),coat);if(a.outfitId>=4)Fill(new Rect(x+5*u,y+21*u,15*u,3*u),trim);if(a.accessoryIds[0]>0){Fill(new Rect(x+3*u,y,19*u,3*u),trim);Fill(new Rect(x+7*u,y-3*u,11*u,4*u),coat);}if(a.accessoryIds[1]>0)Fill(new Rect(x+18*u,y+13*u,2*u,3*u),gold);if(a.accessoryIds[3]>0)Fill(new Rect(x+5*u,y+28*u,15*u,2*u),gold);if(a.accessoryIds[4]>0)Fill(new Rect(x+22*u,y+22*u,2*u,18*u),gold);}







