internal void Save(bool auto){try{if(s==null||smoke)return;s.screen=page;SaveStore.Save(s,auto);if(!auto)Notify("手动存档已保存");}catch(Exception e){Notify("保存失败："+e.Message);Debug.LogException(e);}}
void Load(int index,bool auto,bool backup=false){try{var loaded=SaveStore.Load(index,auto,backup);s=loaded;g=new GameService(c,s);g.Workflow.RestoreOffline(DateTime.UtcNow);page=s.ended&&s.screen=="结局"?"结局":s.atSea?"航海":"城市";paused=false;selectedPort=(s.city+1)%8;SaveStore.Save(s,true);Notify("档案恢复完成；离线进度已按离线档位结算");}catch(Exception e){Notify("读取失败，原档保留："+e.Message);}}
void SmokeStep(){string dir=Path.Combine(Application.dataPath,"..","Evidence");Directory.CreateDirectory(dir);LiveGui.Capture(Path.Combine(dir,"runtime-"+smokeStage+".png"));Debug.Log("RUNTIME_UI stage="+smokeStage+" page="+page+" frames="+guiRepaints);string click=null;switch(smokeStage){case 0:click="Press any key";break;case 1:click="新游戏";break;case 2:click="建立档案";break;case 3:click="东亚 · 女";break;case 4:if(look.baseId!=1)Debug.LogError("UI_TEMPLATE1_FAILED");click="欧洲 · 女";break;case 5:if(look.baseId!=3)Debug.LogError("UI_TEMPLATE2_FAILED");click="下一步";break;case 6:click="经典 · 海战";break;case 7:click="以此家园";break;case 8:if(s==null){Debug.LogError("UI_NEWGAME_FAILED");Application.Quit();return;}click="记入航海日志";break;case 9:click="产业园";break;case 10:click="开始加工";break;case 11:if(s.pendingEvents.Count>0){LiveGui.ClickText("记入航海日志");return;}if(s.orders.Count==0){Debug.LogError("UI_ORDER_FAILED");Application.Quit();return;}if(!s.orders[0].completed)return;click="领取成品";break;case 12:if(!s.orders[0].claimed)Debug.LogError("UI_CLAIM_FAILED");click="市场";break;case 13:if(industry!=3){LiveGui.ClickText("产业筛选");return;}click="买入";break;case 14:if(s.pendingEvents.Count>0){LiveGui.ClickText("记入航海日志");return;}if(s.trades==0)Debug.LogError("UI_TRADE_FAILED");click="海图";break;case 15:click="任务";break;case 16:StartBattle(true);break;case 17:if(s.pendingEvents.Count>0&&page!="战斗"){LiveGui.ClickText("记入航海日志");return;}if(page=="战斗"&&Time.realtimeSinceStartup<150)return;if(!s.ended)Debug.LogError("RUNTIME_COMBAT_FAILED");else Debug.Log("RUNTIME_COMBAT_VICTORY_AND_ENDING");SaveStore.Save(s);var loaded=SaveStore.Load(s.slot);Debug.Log(loaded.ended?"RUNTIME_ENDING_SAVE_PASS":"RUNTIME_ENDING_SAVE_FAIL");click="保存通关档";break;case 18:if(page!="城市")Debug.LogError("RUNTIME_POSTGAME_FAILED");Debug.Log("RUNTIME_SMOKE_COMPLETE");Invoke(nameof(QuitSmoke),1);smokeStage++;return;}if(click!=null&&!LiveGui.ClickText(click))Debug.LogError("UI_BUTTON_NOT_FOUND "+click);smokeStage++;}

void QuitSmoke(){Application.Quit();}
